//
// pfb4_rom — PFB（T = 4）の係数 ROM。**model/pfb4.py gen の生成物。手で直さない**（係数の正は model/pfb4_coef.txt）
//
// P = 0 がタップ 0、P = 1 がタップ 1 の 4096 語（c[a + 4096·P]、Q16・18 bit 符号付き）。2 ポートで読む:
//   ポート A: 番地 a      → タップ P の c[a + 4096·P]
//   ポート B: 番地 4095 − a → 係数の対称で タップ 3 − P の c[a + 4096·(3 − P)]（呼ぶ側が番地を 4095 − a にして渡す）
// 出力は番地から **2 クロック後**（ROM の読み出し + 出力レジスタ）。

`timescale 1ns / 1ps

module pfb4_rom #(
    parameter integer P = 0
)(
    input  wire                  clk,
    input  wire [11:0]           addr_a,
    input  wire [11:0]           addr_b,
    output reg  signed [17:0]   c_a,
    output reg  signed [17:0]   c_b
);
    (* rom_style = "block" *) reg [17:0] rom [0:4095];
    reg [17:0] ra, rb;
    always @(posedge clk) begin
        ra  <= rom[addr_a];
        rb  <= rom[addr_b];
        c_a <= ra;
        c_b <= rb;
    end
    generate
    if (P == 0) begin : g_p0
        initial begin
            rom[0] = 18'h00000;
            rom[1] = 18'h00000;
            rom[2] = 18'h00000;
            rom[3] = 18'h00000;
            rom[4] = 18'h00000;
